const leadData = $input.first().json;
const issues = [];

// RESPA Compliance - Real Estate Settlement Procedures Act
if (!leadData.disclosuresSent) {
  issues.push({
    type: 'RESPA',
    severity: 'high',
    message: 'RESPA disclosures must be sent within 3 business days',
    regulation: '12 CFR § 1024.7'
  });
}

// TILA - Truth in Lending Act
if (!leadData.tilaSent && leadData.applicationReceived) {
  issues.push({
    type: 'TILA',
    severity: 'high',
    message: 'TILA disclosure required within 3 business days of application',
    regulation: '12 CFR § 1026.19'
  });
}

// ECOA - Equal Credit Opportunity Act
if (leadData.status === 'denied' && !leadData.adverseActionNotice) {
  issues.push({
    type: 'ECOA',
    severity: 'critical',
    message: 'Adverse action notice required within 30 days',
    regulation: '12 CFR § 1002.9'
  });
}

// FCRA - Fair Credit Reporting Act
if (leadData.creditPulled && !leadData.fcraConsent) {
  issues.push({
    type: 'FCRA',
    severity: 'critical',
    message: 'Written consent required before pulling credit',
    regulation: '15 USC § 1681b'
  });
}

// HMDA - Home Mortgage Disclosure Act
if (!leadData.hmdaData || !leadData.hmdaData.ethnicity || !leadData.hmdaData.race) {
  issues.push({
    type: 'HMDA',
    severity: 'medium',
    message: 'HMDA demographic data collection incomplete',
    regulation: '12 CFR § 1003.4'
  });
}

// ATR - Ability to Repay Rule
if (leadData.dtiRatio > 43 && !leadData.atrException) {
  issues.push({
    type: 'ATR',
    severity: 'high',
    message: 'DTI ratio exceeds 43% - verify ATR compliance',
    regulation: '12 CFR § 1026.43'
  });
}

// SAFE Act - Secure and Fair Enforcement
if (!leadData.loanOfficerNMLSId || leadData.loanOfficerNMLSId.length < 6) {
  issues.push({
    type: 'SAFE',
    severity: 'critical',
    message: 'Valid NMLS ID required for loan officer',
    regulation: '12 USC § 5103'
  });
}

return [{
  json: {
    leadId: leadData.leadId,
    checkDate: new Date().toISOString(),
    compliant: issues.length === 0,
    issuesCount: issues.length,
    criticalIssues: issues.filter(i => i.severity === 'critical').length,
    highIssues: issues.filter(i => i.severity === 'high').length,
    mediumIssues: issues.filter(i => i.severity === 'medium').length,
    issues: issues
  }
}];
